"NSPhotoLibraryUsageDescription" = "يُستخدم الوصول إلى مكتبة الصور لاختيار الصورة الشخصية والصور ومقاطع الفيديو وصور التحقق من الهوية.";
"NSCameraUsageDescription" = "يُستخدم الوصول إلى الكاميرا لمسح رموز QR والتقاط الصور ومقاطع الفيديو وصور التحقق من الهوية وإجراء مكالمات الفيديو.";
"NSPhotoLibraryAddUsageDescription" = "يُستخدم الوصول إلى مكتبة الصور لحفظ الصور ومقاطع الفيديو في مكتبة الصور لديك.";
"NSMicrophoneUsageDescription" = "يُستخدم الوصول إلى الميكروفون لإرسال الرسائل الصوتية وإجراء المكالمات الصوتية أو مكالمات الفيديو وتسجيل مقاطع الفيديو.";
"NSSpeechRecognitionUsageDescription" = "يُستخدم التعرف على الكلام لتحويل الكلام إلى نص.";

"NSPhotoLibraryUsageDescription" = "Достъпът до снимките се използва за избор на аватари, изображения, видеоклипове и снимки за проверка на самоличността.";
"NSCameraUsageDescription" = "Достъпът до камерата се използва за сканиране на QR кодове, заснемане на снимки и видеоклипове, снимки за проверка на самоличността и видеоразговори.";
"NSPhotoLibraryAddUsageDescription" = "Достъпът до снимките се използва за запазване на изображения и видеоклипове във вашата фотобиблиотека.";
"NSMicrophoneUsageDescription" = "Достъпът до микрофона се използва за изпращане на гласови съобщения, гласови и видеоразговори и запис на видеоклипове.";
"NSSpeechRecognitionUsageDescription" = "Разпознаването на реч се използва за преобразуване на реч в текст.";

"NSPhotoLibraryUsageDescription" = "Přístup k fotografiím slouží k výběru profilových fotek, obrázků, videí a fotografií pro ověření totožnosti.";
"NSCameraUsageDescription" = "Přístup k fotoaparátu slouží ke skenování QR kódů, pořizování fotek a videí, fotografování dokladů pro ověření totožnosti a videohovorům.";
"NSPhotoLibraryAddUsageDescription" = "Přístup k fotografiím slouží k ukládání obrázků a videí do vaší knihovny fotografií.";
"NSMicrophoneUsageDescription" = "Přístup k mikrofonu slouží k odesílání hlasových zpráv, hlasovým hovorům a videohovorům a nahrávání videí.";
"NSSpeechRecognitionUsageDescription" = "Rozpoznávání řeči slouží k převodu řeči na text.";

"NSPhotoLibraryUsageDescription" = "Adgang til fotobiblioteket bruges til at vælge profilbilleder, billeder, videoer og fotos til identitetsbekræftelse.";
"NSCameraUsageDescription" = "Kameraet bruges til at scanne QR-koder, tage billeder og videoer, fotografere identitetsdokumenter og foretage videoopkald.";
"NSPhotoLibraryAddUsageDescription" = "Adgang til fotobiblioteket bruges til at gemme billeder og videoer i dit fotobibliotek.";
"NSMicrophoneUsageDescription" = "Mikrofonen bruges til at sende talebeskeder, foretage tale- eller videoopkald og optage videoer.";
"NSSpeechRecognitionUsageDescription" = "Talegenkendelse bruges til at omdanne tale til tekst.";

"NSPhotoLibraryUsageDescription" = "Der Zugriff auf Fotos wird verwendet, um Profilbilder, Bilder, Videos und Fotos für die Identitätsprüfung auszuwählen.";
"NSCameraUsageDescription" = "Die Kamera wird zum Scannen von QR-Codes, Aufnehmen von Fotos und Videos, Fotografieren von Identitätsdokumenten und für Videoanrufe verwendet.";
"NSPhotoLibraryAddUsageDescription" = "Der Zugriff auf Fotos wird verwendet, um Bilder und Videos in Ihrer Fotomediathek zu speichern.";
"NSMicrophoneUsageDescription" = "Das Mikrofon wird zum Senden von Sprachnachrichten, für Sprach- und Videoanrufe sowie zum Aufnehmen von Videos verwendet.";
"NSSpeechRecognitionUsageDescription" = "Die Spracherkennung wird verwendet, um Sprache in Text umzuwandeln.";

"NSPhotoLibraryUsageDescription" = "Η πρόσβαση στις φωτογραφίες χρησιμοποιείται για την επιλογή εικόνων προφίλ, εικόνων, βίντεο και φωτογραφιών επαλήθευσης ταυτότητας.";
"NSCameraUsageDescription" = "Η πρόσβαση στην κάμερα χρησιμοποιείται για σάρωση κωδικών QR, λήψη φωτογραφιών και βίντεο, λήψη φωτογραφιών επαλήθευσης ταυτότητας και βιντεοκλήσεις.";
"NSPhotoLibraryAddUsageDescription" = "Η πρόσβαση στις φωτογραφίες χρησιμοποιείται για την αποθήκευση εικόνων και βίντεο στη βιβλιοθήκη φωτογραφιών σας.";
"NSMicrophoneUsageDescription" = "Η πρόσβαση στο μικρόφωνο χρησιμοποιείται για αποστολή φωνητικών μηνυμάτων, φωνητικές κλήσεις ή βιντεοκλήσεις και εγγραφή βίντεο.";
"NSSpeechRecognitionUsageDescription" = "Η αναγνώριση ομιλίας χρησιμοποιείται για τη μετατροπή της ομιλίας σε κείμενο.";

"NSPhotoLibraryUsageDescription" = "Photo library access is used to select avatars, images, videos, and identity verification photos.";
"NSCameraUsageDescription" = "Camera access is used to scan QR codes, take photos and videos, capture identity verification photos, and make video calls.";
"NSPhotoLibraryAddUsageDescription" = "Photo library access is used to save images and videos to your photo library.";
"NSMicrophoneUsageDescription" = "Microphone access is used to send voice messages, make voice or video calls, and record videos.";
