"NSPhotoLibraryUsageDescription" = "Ginagamit ang access sa photo library para pumili ng avatar, mga larawan, video, at mga larawan para sa pag-verify ng pagkakakilanlan.";
"NSCameraUsageDescription" = "Ginagamit ang camera para mag-scan ng mga QR code, kumuha ng mga larawan at video, kumuha ng mga larawan para sa pag-verify ng pagkakakilanlan, at magsagawa ng mga video call.";
"NSPhotoLibraryAddUsageDescription" = "Ginagamit ang access sa photo library para mag-save ng mga larawan at video sa iyong photo library.";
"NSMicrophoneUsageDescription" = "Ginagamit ang mikropono para magpadala ng mga voice message, magsagawa ng mga voice o video call, at mag-record ng mga video.";
